package geographic

import (
	"context"
	"database/sql"
	"fmt"
	"net/http"
	"time"

	"github.com/BugraAkdemir/eco-terminal/backend/internal/auth"
	"github.com/BugraAkdemir/eco-terminal/backend/internal/httpx"
)

// Analytics is the RegionAnalytics response. Every number is computed by SQL; nothing here is
// estimated or generated by an LLM.
type Analytics struct {
	RegionID string `json:"region_id"`
	Period   struct {
		From string `json:"from"`
		To   string `json:"to"`
	} `json:"period"`
	Totals struct {
		Observations  int `json:"observations"`
		Issues        int `json:"issues"`
		Verified      int `json:"verified"`
		PendingReview int `json:"pending_review"`
	} `json:"totals"`
	ByCategory    []CategoryCount `json:"by_category"`
	ByMonth       []MonthCount    `json:"by_month"`
	TopSpecies    []SpeciesCount  `json:"top_species"`
	Environmental map[string]any  `json:"environmental"`
	DataQuality   DataQuality     `json:"data_quality"`
}

type CategoryCount struct {
	Category string `json:"category"`
	Count    int    `json:"count"`
}

type MonthCount struct {
	Month             string `json:"month"`
	Count             int    `json:"count"`
	DistinctObservers int    `json:"distinct_observers"`
}

type SpeciesCount struct {
	Species string `json:"species"`
	Count   int    `json:"count"`
}

type DataQuality struct {
	DistinctObservers int      `json:"distinct_observers"`
	MonthsWithData    int      `json:"months_with_data"`
	MonthsInPeriod    int      `json:"months_in_period"`
	Warnings          []string `json:"warnings"`
}

// Warning texts (Turkish, the primary UI language).
const (
	WarnSamplingBias = "Gözlem sayısındaki değişim popülasyon değişimi anlamına gelmez: kayıtlar gönüllü katılıma ve gözlem çabasına bağlıdır (örnekleme yanlılığı)."
)

// Analytics computes region aggregates for the caller's visibility scope: reviewers/admins see all
// non-draft, non-rejected records; everyone else only verified/resolved ones.
func (s *Service) Analytics(ctx context.Context, regionID, from, to string, staff bool) (*Analytics, error) {
	ok, err := s.Exists(ctx, regionID)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, httpx.NotFound("region not found")
	}
	statuses := `'verified','resolved'`
	if staff {
		statuses = `'submitted','ai_processed','under_review','needs_information','verified','resolved'`
	}
	scope := `FROM observations o JOIN observation_region_links l ON l.observation_id = o.id
		WHERE l.region_id = ? AND o.deleted_at IS NULL AND o.status IN (` + statuses + `)`
	now := time.Now().UTC()
	if to == "" {
		to = now.Format(time.RFC3339)
	}
	if from == "" {
		var minObs sql.NullString
		if err := s.db.QueryRowContext(ctx, `SELECT min(o.observed_at) `+scope, regionID).Scan(&minObs); err != nil {
			return nil, err
		}
		if minObs.Valid {
			from = minObs.String
		} else {
			from = now.AddDate(0, -11, 0).Format("2006-01") + "-01T00:00:00Z"
		}
	}
	tf, err1 := time.Parse(time.RFC3339, from)
	tt, err2 := time.Parse(time.RFC3339, to)
	if err1 != nil || err2 != nil {
		return nil, httpx.Validation("from/to must be RFC3339 or YYYY-MM-DD", nil)
	}
	if tt.Before(tf) {
		return nil, httpx.Validation("to must not be before from", nil)
	}
	scope += ` AND o.observed_at >= ? AND o.observed_at <= ?`
	args := []any{regionID, from, to}

	a := &Analytics{RegionID: regionID, ByCategory: []CategoryCount{}, ByMonth: []MonthCount{}, TopSpecies: []SpeciesCount{}}
	a.Period.From, a.Period.To = from, to

	// totals
	if err := s.db.QueryRowContext(ctx, `SELECT
		COALESCE(SUM(o.record_type='observation'),0), COALESCE(SUM(o.record_type='issue'),0),
		COALESCE(SUM(o.status IN ('verified','resolved')),0),
		COALESCE(SUM(o.status IN ('submitted','ai_processed','under_review','needs_information')),0),
		count(DISTINCT o.user_id) `+scope, args...).
		Scan(&a.Totals.Observations, &a.Totals.Issues, &a.Totals.Verified, &a.Totals.PendingReview,
			&a.DataQuality.DistinctObservers); err != nil {
		return nil, err
	}
	var demoCount, total int
	if err := s.db.QueryRowContext(ctx, `SELECT COALESCE(SUM(o.is_demo),0), count(*) `+scope, args...).Scan(&demoCount, &total); err != nil {
		return nil, err
	}

	// by category
	rows, err := s.db.QueryContext(ctx, `SELECT o.category, count(*) `+scope+` GROUP BY o.category ORDER BY count(*) DESC, o.category`, args...)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var c CategoryCount
		if err := rows.Scan(&c.Category, &c.Count); err != nil {
			rows.Close()
			return nil, err
		}
		a.ByCategory = append(a.ByCategory, c)
	}
	rows.Close()

	// by month
	counts := map[string]MonthCount{}
	rows, err = s.db.QueryContext(ctx, `SELECT substr(o.observed_at,1,7), count(*), count(DISTINCT o.user_id) `+scope+
		` GROUP BY substr(o.observed_at,1,7) ORDER BY 1`, args...)
	if err != nil {
		return nil, err
	}
	var existing []MonthCount
	for rows.Next() {
		var m MonthCount
		if err := rows.Scan(&m.Month, &m.Count, &m.DistinctObservers); err != nil {
			rows.Close()
			return nil, err
		}
		counts[m.Month] = m
		existing = append(existing, m)
	}
	rows.Close()
	a.DataQuality.MonthsWithData = len(existing)
	months := monthsBetween(tf, tt)
	a.DataQuality.MonthsInPeriod = len(months)
	if len(months) <= 240 { // zero-fill so charts have a continuous axis
		for _, mo := range months {
			if m, ok := counts[mo]; ok {
				a.ByMonth = append(a.ByMonth, m)
			} else {
				a.ByMonth = append(a.ByMonth, MonthCount{Month: mo})
			}
		}
	} else {
		a.ByMonth = append(a.ByMonth, existing...)
	}

	// top species (reviewer-confirmed names only; unverified guesses are never aggregated)
	rows, err = s.db.QueryContext(ctx, `SELECT o.species_verified, count(*) `+scope+` AND o.species_verified <> ''
		GROUP BY o.species_verified ORDER BY count(*) DESC, o.species_verified LIMIT 10`, args...)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var sc SpeciesCount
		if err := rows.Scan(&sc.Species, &sc.Count); err != nil {
			rows.Close()
			return nil, err
		}
		a.TopSpecies = append(a.TopSpecies, sc)
	}
	rows.Close()

	// environmental summary (only when measurements exist for this region and period)
	var days int
	var precip, temp sql.NullFloat64
	if err := s.db.QueryRowContext(ctx, `SELECT
		count(DISTINCT substr(ts,1,10)),
		SUM(CASE WHEN measurement_type='precipitation' THEN value END),
		AVG(CASE WHEN measurement_type='temperature_mean' THEN value END)
		FROM environmental_measurements WHERE region_id = ? AND substr(ts,1,10) >= ? AND substr(ts,1,10) <= ?`,
		regionID, from[:10], to[:10]).Scan(&days, &precip, &temp); err != nil {
		return nil, err
	}
	if days > 0 {
		env := map[string]any{"measurement_days": days}
		if precip.Valid {
			env["precipitation_total_mm"] = precip.Float64
		}
		if temp.Valid {
			env["temperature_mean_c"] = temp.Float64
		}
		a.Environmental = env
	}

	// data quality warnings
	w := []string{WarnSamplingBias}
	switch {
	case total == 0:
		w = append(w, "Bu bölge ve dönem için görüntülenebilir kayıt bulunmuyor.")
	default:
		if a.DataQuality.DistinctObservers < 5 {
			w = append(w, fmt.Sprintf("Yalnızca %d farklı gözlemci katkıda bulundu; sonuçlar birkaç kişinin gözlem alışkanlıklarını yansıtıyor olabilir.", a.DataQuality.DistinctObservers))
		}
		if total < 30 {
			w = append(w, fmt.Sprintf("Toplam kayıt sayısı (%d) istatistiksel çıkarım için düşük.", total))
		}
		if a.DataQuality.MonthsInPeriod > 1 && a.DataQuality.MonthsWithData*2 < a.DataQuality.MonthsInPeriod {
			w = append(w, fmt.Sprintf("Dönemin %d ayından yalnızca %d ayında kayıt var; seyrek veri nedeniyle zaman serisi yorumlanmamalı.",
				a.DataQuality.MonthsInPeriod, a.DataQuality.MonthsWithData))
		}
		if demoCount == total {
			w = append(w, "Bu sonuçların tamamı demo verisinden oluşuyor; gerçek bir gözlem değildir.")
		} else if demoCount > 0 {
			w = append(w, fmt.Sprintf("Sayılan kayıtların %d tanesi demo verisidir.", demoCount))
		}
	}
	if !staff {
		w = append(w, "Yalnızca doğrulanmış kayıtlar sayılır; bekleyen kayıt sayısı yalnızca uzman kullanıcılara gösterilir.")
	}
	a.DataQuality.Warnings = w
	return a, nil
}

// monthsBetween lists YYYY-MM from the month of a through the month of b inclusive.
func monthsBetween(a, b time.Time) []string {
	var out []string
	cur := time.Date(a.Year(), a.Month(), 1, 0, 0, 0, 0, time.UTC)
	end := time.Date(b.Year(), b.Month(), 1, 0, 0, 0, 0, time.UTC)
	for !cur.After(end) && len(out) < 5000 {
		out = append(out, cur.Format("2006-01"))
		cur = cur.AddDate(0, 1, 0)
	}
	return out
}

func (s *Service) handleAnalytics(w http.ResponseWriter, r *http.Request) {
	var from, to string
	var err error
	if v := r.URL.Query().Get("from"); v != "" {
		if from, err = httpx.ParseTimeParam("from", v, false); err != nil {
			httpx.WriteError(w, err)
			return
		}
	}
	if v := r.URL.Query().Get("to"); v != "" {
		if to, err = httpx.ParseTimeParam("to", v, true); err != nil {
			httpx.WriteError(w, err)
			return
		}
	}
	u, _ := auth.UserFrom(r.Context())
	a, err := s.Analytics(r.Context(), r.PathValue("id"), from, to, auth.IsStaff(u))
	if err != nil {
		httpx.WriteError(w, err)
		return
	}
	httpx.WriteJSON(w, http.StatusOK, a)
}
